import { existsSync, mkdirSync, readdirSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";

import type { StoryboardSource } from "@/lib/storyboard";

/** Where generated storyboards live, and how the app finds them. */
export interface StoryboardWriter {
  exists(problem: string): boolean;
  write(problem: string, storyboard: StoryboardSource): void;
}

const HEADER =
  "// Generated by scripts/generate-storyboards.ts. Do not edit by hand: rerun the script instead.";

const identifier = (problem: string) =>
  problem.replace(/[^a-zA-Z0-9]+(.)/g, (_, c: string) => c.toUpperCase()).replace(/^[^a-zA-Z]/, "_");

/** Rebuild `index.ts` from the JSON files on disk, so the registry always matches the folder. */
export function renderRegistry(problems: readonly string[]): string {
  const sorted = [...problems].sort();
  const imports = sorted.map((p) => `import ${identifier(p)} from "./${p}.json";`).join("\n");
  const entries = sorted.map((p) => `  "${p}": loadStoryboard(${identifier(p)}),`).join("\n");
  return `${HEADER}
import { loadStoryboard, type Storyboard } from "@/lib/storyboard";
${imports ? `\n${imports}\n` : ""}
/** Generated storyboards keyed by catalog problem ("pattern/slug"). */
export const generatedStoryboards: Readonly<Record<string, Storyboard>> = {${entries ? `\n${entries}\n` : ""}};
`;
}

function listProblems(root: string): string[] {
  if (!existsSync(root)) return [];
  return readdirSync(root)
    .filter((pattern) => statSync(path.join(root, pattern)).isDirectory())
    .flatMap((pattern) =>
      readdirSync(path.join(root, pattern))
        .filter((f) => f.endsWith(".json"))
        .map((f) => `${pattern}/${f.replace(/\.json$/, "")}`),
    );
}

/** Writes `<root>/<pattern>/<slug>.json` and regenerates `<root>/index.ts`. */
export function createFileWriter(root: string): StoryboardWriter {
  return {
    exists: (problem) => existsSync(path.join(root, `${problem}.json`)),
    write(problem, storyboard) {
      const file = path.join(root, `${problem}.json`);
      mkdirSync(path.dirname(file), { recursive: true });
      writeFileSync(file, `${JSON.stringify(storyboard, null, 2)}\n`);
      writeFileSync(path.join(root, "index.ts"), renderRegistry(listProblems(root)));
    },
  };
}
